{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.cappyeo/discord-mcp",
  "title": "Discord MCP",
  "description": "Connect AI clients to a caller-owned Discord bot with 201 tools over stdio or authenticated HTTP.",
  "repository": {
    "url": "https://github.com/cappyeo/discord-mcp",
    "source": "github",
    "id": "1223078565",
    "subfolder": "packages/mcp-server"
  },
  "version": "0.16.11",
  "websiteUrl": "https://cappyeo.github.io/discord-mcp/",
  "icons": [
    {
      "src": "https://raw.githubusercontent.com/cappyeo/discord-mcp/v0.16.11/site/src/assets/discord-mcp-logo-light.png",
      "mimeType": "image/png",
      "sizes": ["1024x1024"],
      "theme": "light"
    },
    {
      "src": "https://raw.githubusercontent.com/cappyeo/discord-mcp/v0.16.11/site/src/assets/discord-mcp-logo-dark.png",
      "mimeType": "image/png",
      "sizes": ["1024x1024"],
      "theme": "dark"
    }
  ],
  "packages": [
    {
      "registryType": "npm",
      "identifier": "@discord-mcp/cli",
      "version": "0.16.11",
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
          "description": "Discord bot token. The optional Bot prefix is accepted.",
          "isRequired": true,
          "format": "string",
          "isSecret": true,
          "name": "DISCORD_TOKEN"
        },
        {
          "description": "Expected Discord bot ID. Startup fails if the token belongs to another bot.",
          "isRequired": false,
          "format": "string",
          "isSecret": false,
          "name": "DISCORD_EXPECTED_BOT_ID"
        },
        {
          "description": "Comma-separated Discord guild IDs this deployment may operate against.",
          "isRequired": false,
          "format": "string",
          "isSecret": false,
          "name": "ALLOWED_GUILDS"
        }
      ]
    }
  ]
}

{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.codeofaxel/kiln",
  "title": "Kiln",
  "description": "Kiln MCP server for agents: design, slice, print, monitor, and recover physical objects safely.",
  "version": "1.3.2",
  "repository": {
    "url": "https://github.com/codeofaxel/Kiln",
    "source": "github"
  },
  "websiteUrl": "https://kiln3d.com/?utm_source=mcp-registry&utm_medium=listing",
  "packages": [
    {
      "registryType": "pypi",
      "identifier": "kiln3d",
      "version": "1.3.2",
      "runtimeHint": "uvx",
      "packageArguments": [
        {
          "type": "positional",
          "value": "serve"
        }
      ],
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
          "name": "KILN_PRINTER_HOST",
          "description": "URL of your 3D printer (OctoPrint, Moonraker, Creality, or Prusa Link)",
          "isRequired": false,
          "isSecret": false
        },
        {
          "name": "KILN_PRINTER_API_KEY",
          "description": "API key for your printer's REST API",
          "isRequired": false,
          "isSecret": true
        },
        {
          "name": "KILN_PRINTER_TYPE",
          "description": "Printer type: octoprint, moonraker, creality, bambu, prusalink, elegoo, or serial",
          "isRequired": false,
          "isSecret": false
        }
      ]
    }
  ]
}

